from taf.nms.nsp.nfmp.connection.connection import Connection
from taf.nms.nsp.nfmp.exception import SchemaParseError
from taf.nms.nsp.nfmp.schemas.nfmp19.schemas import SupportedSchemas
from taf.nms.nsp.nfmp.schemas.nfmp19.messages import SupportedMessages


class Nfmp19(object):
    """
    All the operation will be defined in this class.
    This class should at least contain 'NFMP_VERSION' to
    to define the current NFMP's version and 'API_VERSION' to define which version of XML api wil
    be used.
    """
    NFMP_VERSION = 19
    API_VERSION = '1.0'
    COMPONENT_CLASS_NAME = {
        'mrbts_info': 'netw.NetworkElement',
        'hw_info': 'racgnb.HW',
        'cabinet_info': 'racgnb.CABINET_INV',
        'smod_inv_info': 'racgnb.SMOD_INV',
        'fan_inv_info': 'racgnb.FAN_INV',
        'gnsse_inv_info': 'racgnb.GNSSE_INV',
        'rmod_inv_info': 'racgnb.RMOD_INV',
        'passdev_inv_info': 'racgnb.PASSDEV_INV'
    }

    def __init__(self, ip, username, password, port):
        self._connection = Connection(ip, username, password, port)
        self.msg_body = SupportedMessages.msg_schema(username=username, password=password)

    def reset_mrbts(self, site_id):
        reset_mrbts_shcema = SupportedMessages.reset_mrbts(
            instance_full_name='network:{}:{}'.format(site_id, site_id)
        )
        api_response = self._connection.send_request(self.msg_body.get_xml(body=reset_mrbts_shcema))
        SupportedSchemas.reset_mrbts.from_xml(api_response)

    def change_nrcell_administrative_state(self, site_id, state):
        change_nrcell_administrative_schema = SupportedMessages.change_nrcell_administrative_state(
            distinguished_name='network:{}:{}:NRBTS-1:NRCELL-1'.format(site_id, site_id),
            state=state
        )
        api_response = self._connection.send_request(self.msg_body.get_xml(body=change_nrcell_administrative_schema))
        return SupportedSchemas.nrcell_info.from_xml(api_response)

    def get_alarms(self):
        get_alarms_schema = SupportedMessages.get_alarms()
        api_response = self._connection.send_request(self.msg_body.get_xml(body=get_alarms_schema))
        return SupportedSchemas.alarm_list.from_xml(api_response).to_dict()

    def set_vnf_to_active(self, bts_id):
        set_to_active_msg = SupportedMessages.set_to_active(bts_id=bts_id)
        api_response = self._connection.send_request(
            self.msg_body.get_xml(body=set_to_active_msg))

        try:
            _ = SupportedSchemas.set_to_active_response.from_xml(api_response)
        except SchemaParseError:
            exc_data = SupportedSchemas.set_to_active_exception.from_xml(api_response)
            raise RuntimeError(str(exc_data))

    def set_vnf_to_standby(self, bts_id):
        set_to_standby_msg = SupportedMessages.set_to_standby(bts_id=bts_id)
        api_response = self._connection.send_request(
            self.msg_body.get_xml(body=set_to_standby_msg))

        try:
            _ = SupportedSchemas.set_to_standby_response.from_xml(api_response)
        except SchemaParseError:
            exc_data = SupportedSchemas.set_to_standby_exception.from_xml(api_response)
            raise RuntimeError(str(exc_data))

    def _get_hw_info(self, hw_type, full_class_name, site_id, module_id):
        get_module_info_schema = SupportedMessages.get_module_info(full_class_name=full_class_name,
                                                                   site_id=site_id,
                                                                   module_id=module_id)
        api_response = self._connection.send_request(self.msg_body.get_xml(body=get_module_info_schema))
        return getattr(SupportedSchemas, hw_type).from_xml(api_response)

    def get_mrbts_component_general_info(self, site_id, module_id):
        return self._get_hw_info('mrbts_info', self.COMPONENT_CLASS_NAME['mrbts_info'], site_id, module_id)

    def get_hw_component_general_info(self, site_id, module_id):
        return self._get_hw_info('hw_info', self.COMPONENT_CLASS_NAME['hw_info'], site_id, module_id)

    def get_cabinet_component_general_info(self, site_id, module_id):
        return self._get_hw_info('cabinet_info', self.COMPONENT_CLASS_NAME['cabinet_info'], site_id, module_id)

    def get_smod_inv_component_general_info(self, site_id, module_id):
        return self._get_hw_info('smod_inv_info', self.COMPONENT_CLASS_NAME['smod_inv_info'], site_id, module_id)

    def get_fan_inv_component_general_info(self, site_id, module_id):
        return self._get_hw_info('fan_inv_info', self.COMPONENT_CLASS_NAME['fan_inv_info'], site_id, module_id)

    def get_gnsse_inv_component_general_info(self, site_id, module_id):
        return self._get_hw_info('gnsse_inv_info', self.COMPONENT_CLASS_NAME['gnsse_inv_info'], site_id, module_id)

    def get_rmod_inv_component_general_info(self, site_id, module_id):
        return self._get_hw_info('rmod_inv_info', self.COMPONENT_CLASS_NAME['rmod_inv_info'], site_id, module_id)

    def get_passdev_inv_component_general_info(self, site_id, module_id):
        return self._get_hw_info('passdev_inv_info', self.COMPONENT_CLASS_NAME['passdev_inv_info'], site_id, module_id)

    def update_from_peer_node(self, bts_id):
        msg = SupportedMessages.update_from_peer_node(bts_id=bts_id)
        api_response = self._connection.send_request(
            self.msg_body.get_xml(body=msg))

        try:
            _ = SupportedSchemas.update_from_peer_node_response.from_xml(api_response)
        except SchemaParseError:
            exc_data = SupportedSchemas.update_from_peer_node_exception.from_xml(api_response)
            raise RuntimeError(str(exc_data))
